/// <summary>
/// heartbeatClaim's and releaseJournal's request - the token claimJournal handed out.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountClaimTokenRequest
{
    DataAreaId      dataAreaId;
    InventJournalId journalId;
    str             claimToken;
    str             userId;
    str             deviceId;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('JournalId')]
public InventJournalId parmJournalId(InventJournalId _value = journalId)
{
    journalId = _value;
    return journalId;
}

[DataMemberAttribute('ClaimToken')]
public str parmClaimToken(str _value = claimToken)
{
    claimToken = _value;
    return claimToken;
}

[DataMemberAttribute('UserId')]
public str parmUserId(str _value = userId)
{
    userId = _value;
    return userId;
}

[DataMemberAttribute('DeviceId')]
public str parmDeviceId(str _value = deviceId)
{
    deviceId = _value;
    return deviceId;
}
